$parentTop = $parent; unset($parentTop["records"]);
$currentTop = $current; unset($currentTop["records"]);
if ($parentTop !== $currentTop) { fwrite(STDERR, "top-level metadata changed\\n"); exit(2); }
echo "top_level_metadata: unchanged\\n";
$indexByArchive = static function (array $records): array {
    $indexed = [];
    foreach ($records as $record) { $indexed[$record["archive"]] = $record; }
    ksort($indexed);
    return $indexed;
};
$before = $indexByArchive($parent["records"]);
$after = $indexByArchive($current["records"]);
$added = array_values(array_diff(array_keys($after), array_keys($before)));
$removed = array_values(array_diff(array_keys($before), array_keys($after)));
