            $walk($old[$key], $new[$key], $child);
        }
        return;
    }
    if ($old !== $new) { $changes[$path] = [$old, $new]; }
};
foreach ($before as $archive => $record) { $walk($record, $after[$archive], $archive); }
ksort($changes);
printf("changed_field_count: %d\\n", count($changes));
$changedRecords = [];
foreach ($changes as $path => [$old, $new]) {
    $archive = strstr($path, ".", true);
    $changedRecords[$archive] = true;
    printf("movement: %s: %s -> %s\\n", $path, json_encode($old, JSON_UNESCAPED_SLASHES), json_encode($new, JSON_UNESCAPED_SLASHES));
